		err := verifier.CorrectSubnet(dataColumnSidecarSubTopic, subnets)
		require.NoError(t, err)
		require.IsNil(t, verifier.results.result(RequireCorrectSubnet))

		err = verifier.CorrectSubnet(dataColumnSidecarSubTopic, subnets)
		require.NoError(t, err)
	})
}

